-- Quotes organ -- generated by noctusai_lib.domain.quotes.sql (do not hand-edit)

SET search_path = commerce, public;

-- Per-org quote number sequence (advanced ONLY by quo_next_number).
CREATE TABLE IF NOT EXISTS commerce.quo_counters (
    org_id       UUID PRIMARY KEY,
    last_number  BIGINT NOT NULL DEFAULT 0 CHECK (last_number >= 0)
);
ALTER TABLE commerce.quo_counters ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "quo_counters_select_own_org" ON commerce.quo_counters;
CREATE POLICY "quo_counters_select_own_org" ON commerce.quo_counters FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.quo_counters;
CREATE POLICY "service_role_bypass" ON commerce.quo_counters FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.quo_counters TO authenticated;
GRANT ALL ON commerce.quo_counters TO service_role;

-- Quotes (orçamentos / propostas). One row per VERSION; `convert_to` NULL = derive from the lines at accept time; `root_id` ties the revisions of one quote together (`root_id = id` on version 1). Money is integer cents; a quote that left draft is frozen (trigger).
CREATE TABLE IF NOT EXISTS commerce.quo_quotes (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id              UUID NOT NULL,
    number              TEXT NOT NULL CHECK (btrim(number) <> ''),
    root_id             UUID NOT NULL,
    version             INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    is_current          BOOLEAN NOT NULL DEFAULT true,
    party_id            UUID NOT NULL,
    title               TEXT,
    status              TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'sent', 'viewed', 'accepted', 'rejected', 'expired', 'superseded')),
    currency            TEXT NOT NULL DEFAULT 'BRL' CHECK (currency ~ '^[A-Z]{3}$'),
    valid_until         DATE,
    notes               TEXT,
    terms               TEXT,
    convert_to          TEXT CHECK (convert_to IS NULL OR convert_to IN ('order', 'contract', 'none')),
    subtotal_cents      BIGINT NOT NULL DEFAULT 0 CHECK (subtotal_cents >= 0),
    discount_cents      BIGINT NOT NULL DEFAULT 0 CHECK (discount_cents >= 0),
    total_cents         BIGINT NOT NULL DEFAULT 0 CHECK (total_cents >= 0),
    sent_at             TIMESTAMPTZ,
    last_sent_to        TEXT,
    viewed_at           TIMESTAMPTZ,
    accepted_at         TIMESTAMPTZ,
    rejected_at         TIMESTAMPTZ,
    expired_at          TIMESTAMPTZ,
    rejection_reason    TEXT,
    conversion_status   TEXT NOT NULL DEFAULT 'none' CHECK (conversion_status IN ('none', 'pending', 'done', 'failed', 'skipped')),
    conversion_kind     TEXT,
    conversion_ref      TEXT,
    conversion_error    TEXT,
    signature_ref       TEXT,
    signature_status    TEXT,
    created_by          UUID,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, org_id),
    CHECK (total_cents = subtotal_cents - discount_cents),
    CHECK ((status = 'accepted') = (accepted_at IS NOT NULL)),
    FOREIGN KEY (party_id, org_id) REFERENCES commerce.pty_parties (id, org_id) ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_quo_quotes_version ON commerce.quo_quotes (org_id, root_id, version);
CREATE UNIQUE INDEX IF NOT EXISTS uq_quo_quotes_number ON commerce.quo_quotes (org_id, number, version);
CREATE UNIQUE INDEX IF NOT EXISTS uq_quo_quotes_current ON commerce.quo_quotes (org_id, root_id) WHERE is_current;
CREATE UNIQUE INDEX IF NOT EXISTS uq_quo_quotes_accepted ON commerce.quo_quotes (org_id, root_id) WHERE status = 'accepted';
CREATE INDEX IF NOT EXISTS idx_quo_quotes_status ON commerce.quo_quotes (org_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_quo_quotes_party ON commerce.quo_quotes (org_id, party_id);
CREATE INDEX IF NOT EXISTS idx_quo_quotes_due ON commerce.quo_quotes (org_id, valid_until) WHERE status IN ('sent', 'viewed');

CREATE OR REPLACE FUNCTION commerce.quo_quotes_frozen() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.status <> 'draft' THEN
            RAISE EXCEPTION 'quo_quotes: only a draft can be deleted' USING ERRCODE = 'QU003';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.status <> 'draft' AND (NEW.number IS DISTINCT FROM OLD.number OR NEW.root_id IS DISTINCT FROM OLD.root_id OR NEW.version IS DISTINCT FROM OLD.version OR NEW.party_id IS DISTINCT FROM OLD.party_id OR NEW.title IS DISTINCT FROM OLD.title OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.valid_until IS DISTINCT FROM OLD.valid_until OR NEW.notes IS DISTINCT FROM OLD.notes OR NEW.terms IS DISTINCT FROM OLD.terms OR NEW.convert_to IS DISTINCT FROM OLD.convert_to OR NEW.subtotal_cents IS DISTINCT FROM OLD.subtotal_cents OR NEW.discount_cents IS DISTINCT FROM OLD.discount_cents OR NEW.total_cents IS DISTINCT FROM OLD.total_cents OR NEW.created_by IS DISTINCT FROM OLD.created_by) THEN
        RAISE EXCEPTION 'quo_quotes: a quote that left draft is frozen -- revise it as a new version' USING ERRCODE = 'QU003';
    END IF;
    RETURN NEW;
END;
$fn$;
DROP TRIGGER IF EXISTS quo_quotes_frozen ON commerce.quo_quotes;
CREATE TRIGGER quo_quotes_frozen BEFORE UPDATE OR DELETE ON commerce.quo_quotes
    FOR EACH ROW EXECUTE FUNCTION commerce.quo_quotes_frozen();
ALTER TABLE commerce.quo_quotes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "quo_quotes_select_own_org" ON commerce.quo_quotes;
CREATE POLICY "quo_quotes_select_own_org" ON commerce.quo_quotes FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.quo_quotes;
CREATE POLICY "service_role_bypass" ON commerce.quo_quotes FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.quo_quotes TO authenticated;
GRANT ALL ON commerce.quo_quotes TO service_role;

-- Quote lines. `kind` (goods | service) drives convert-on-accept; `item_id` is optional (a free-text line is allowed); description / unit / price are SNAPSHOTS. Frozen with their quote (trigger).
CREATE TABLE IF NOT EXISTS commerce.quo_lines (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id           UUID NOT NULL,
    quote_id         UUID NOT NULL,
    position         INTEGER NOT NULL CHECK (position >= 0),
    item_id          UUID REFERENCES commerce.itm_items(id) ON DELETE RESTRICT,
    description      TEXT NOT NULL CHECK (btrim(description) <> ''),
    unit             TEXT NOT NULL DEFAULT 'UN',
    kind             TEXT NOT NULL DEFAULT 'goods' CHECK (kind IN ('goods', 'service')),
    qty              NUMERIC(18,3) NOT NULL CHECK (qty > 0),
    unit_price_cents BIGINT NOT NULL CHECK (unit_price_cents >= 0),
    discount_cents   BIGINT NOT NULL DEFAULT 0 CHECK (discount_cents >= 0),
    total_cents      BIGINT NOT NULL CHECK (total_cents >= 0),
    UNIQUE (quote_id, position),
    FOREIGN KEY (quote_id, org_id) REFERENCES commerce.quo_quotes (id, org_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_quo_lines_item ON commerce.quo_lines (org_id, item_id) WHERE item_id IS NOT NULL;

CREATE OR REPLACE FUNCTION commerce.quo_lines_frozen() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE v_status TEXT;
BEGIN
    SELECT status INTO v_status FROM commerce.quo_quotes
        WHERE id = COALESCE(NEW.quote_id, OLD.quote_id) AND org_id = COALESCE(NEW.org_id, OLD.org_id);
    IF v_status IS NOT NULL AND v_status <> 'draft' THEN
        RAISE EXCEPTION 'quo_lines: the lines of a quote that left draft are frozen' USING ERRCODE = 'QU003';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$fn$;
DROP TRIGGER IF EXISTS quo_lines_frozen ON commerce.quo_lines;
CREATE TRIGGER quo_lines_frozen BEFORE INSERT OR UPDATE OR DELETE ON commerce.quo_lines
    FOR EACH ROW EXECUTE FUNCTION commerce.quo_lines_frozen();
ALTER TABLE commerce.quo_lines ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "quo_lines_select_own_org" ON commerce.quo_lines;
CREATE POLICY "quo_lines_select_own_org" ON commerce.quo_lines FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.quo_lines;
CREATE POLICY "service_role_bypass" ON commerce.quo_lines FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.quo_lines TO authenticated;
GRANT ALL ON commerce.quo_lines TO service_role;

-- Customer decisions (the consent record): who, when, from where, the EXACT consent text shown and the sha256 of the terms decided on. ONE decision per quote version. APPEND-ONLY.
CREATE TABLE IF NOT EXISTS commerce.quo_acceptances (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id          UUID NOT NULL,
    quote_id        UUID NOT NULL,
    decision        TEXT NOT NULL CHECK (decision IN ('accepted', 'rejected')),
    channel         TEXT NOT NULL CHECK (channel IN ('public_link', 'staff')),
    signer_name     TEXT NOT NULL CHECK (btrim(signer_name) <> ''),
    reason          TEXT,
    consent_text    TEXT,
    content_sha256  TEXT NOT NULL CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),
    ip              TEXT,
    user_agent      TEXT,
    decided_by      UUID,
    decided_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (org_id, quote_id),
    CHECK (decision <> 'accepted' OR consent_text IS NOT NULL OR channel = 'staff'),
    FOREIGN KEY (quote_id, org_id) REFERENCES commerce.quo_quotes (id, org_id) ON DELETE RESTRICT
);

