LANGUAGE plpgsql
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
BEGIN
    RAISE EXCEPTION 'quo_acceptances is append-only (% refused)', TG_OP USING ERRCODE = 'QU002';
END;
$fn$;
