ALTER TABLE commerce.quo_acceptances ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "quo_acceptances_select_own_org" ON commerce.quo_acceptances;
CREATE POLICY "quo_acceptances_select_own_org" ON commerce.quo_acceptances FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.quo_acceptances;
CREATE POLICY "service_role_bypass" ON commerce.quo_acceptances FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.quo_acceptances TO authenticated;
GRANT ALL ON commerce.quo_acceptances TO service_role;

-- Audit trail of a quote (APPEND-ONLY, no FK so deleting a draft leaves its history).
CREATE TABLE IF NOT EXISTS commerce.quo_events (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    seq          BIGINT GENERATED ALWAYS AS IDENTITY,
    org_id       UUID NOT NULL,
    quote_id     UUID NOT NULL,
    kind         TEXT NOT NULL CHECK (kind IN ('created', 'updated', 'deleted', 'sent', 'viewed', 'accepted', 'rejected', 'expired', 'superseded', 'versioned', 'converted', 'conversion_failed', 'signature_requested', 'signature_updated')),
    from_status  TEXT,
    to_status    TEXT,
    actor        UUID,
    detail       JSONB NOT NULL DEFAULT '{}'::jsonb,
    at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (jsonb_typeof(detail) = 'object')
);
CREATE INDEX IF NOT EXISTS idx_quo_events_quote ON commerce.quo_events (org_id, quote_id, seq);

