-- The per-org number: one atomic upsert-returning (no read-then-write race). service_role only.
CREATE OR REPLACE FUNCTION commerce.quo_next_number(p_org UUID) RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE v_n BIGINT;
BEGIN
    INSERT INTO commerce.quo_counters (org_id, last_number) VALUES (p_org, 1)
        ON CONFLICT (org_id) DO UPDATE SET last_number = commerce.quo_counters.last_number + 1
        RETURNING last_number INTO v_n;
    RETURN v_n;
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.quo_next_number(UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.quo_next_number(UUID) TO service_role;
